import { useState, useEffect } from 'react';
import styles from './SummaryCard.module.css';

const SummaryCard = ({ totalIncome, totalExpenses, balance, currentBalance }) => {
  // Estado inicial basado en localStorage
  const [financialData, setFinancialData] = useState(() => {
    const savedData = localStorage.getItem('financialSummary');
    return savedData 
      ? JSON.parse(savedData)
      : { totalIncome: 0, totalExpenses: 0, balance: 0, currentBalance: 0 };
  });

  // Actualizar localStorage cuando cambien los props
  useEffect(() => {
    const newData = {
      totalIncome,
      totalExpenses,
      balance,
      currentBalance,
    };
    setFinancialData(newData);
    localStorage.setItem('financialSummary', JSON.stringify(newData));
  }, [totalIncome, totalExpenses, balance, currentBalance]);

  return (
    <div className={styles.card}>
      <h3>Resumen Financiero</h3>
      <div className={styles.summaryItem}>
        <p>Ingresos: ${financialData.totalIncome}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Gastos: ${financialData.totalExpenses}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Balance: ${financialData.balance}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Saldo Actual: ${financialData.currentBalance}</p>
      </div>
    </div>
  );
};

export default SummaryCard;
